const id = $input.first().json.position_id;
if (typeof id !== 'string' || id.trim() === '') {
  throw new Error('position_id is required');
}
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id.trim())) {
  throw new Error('position_id must be a UUID');
}
return [{ json: { position_id: id.trim().toLowerCase() } }];

const rows = $input.all();
if (rows.length === 0 || !rows[0].json.result) {
  throw new Error('position not found');
}
return [{ json: rows[0].json.result }];
